#!/usr/bin/env node
// Compare help/usage output between reference and port under explicit COLUMNS values.
import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test10_executable';
const norm = (s) => s.replace(/^\[PYI-\d+:ERROR\].*$/gm, '[PYI:ERROR]');

const colsList = ['1', '2', '5', '10', '11', '12', '13', '15', '20', '21', '22', '25', '30',
  '31', '32', '33', '34', '35', '40', '43', '44', '45', '46', '47', '48', '49', '50',
  '60', '70', '79', '80', '81', '100', '200', '0', '-1', 'abc', '', ' 40 ', '40x', '+40', '4_0'];
const argvList = [
  ['--help'],
  ['-h'],
  [],
  ['--b', 'zz'],
  ['--zzz'],
  ['--a', 'x', '--b', '1', '--c', '1.5', 'extra'],
  ['--a'],
  ['--h'],
];

let pass = 0, total = 0;
const fails = [];
for (const cols of colsList) {
  for (const argv of argvList) {
    total++;
    const env = { ...process.env, COLUMNS: cols };
    const a = spawnSync(REF, argv, { encoding: 'buffer', env });
    const b = spawnSync('node', ['/output/test10.mjs', ...argv], { encoding: 'buffer', env });
    const ao = a.stdout.toString('binary'), bo = b.stdout.toString('binary');
    const ae = norm(a.stderr.toString('binary')), be = norm(b.stderr.toString('binary'));
    const ok = ao === bo && ae === be && a.status === b.status;
    if (ok) pass++;
    else fails.push({ cols, argv, py: { out: ao, err: ae, rc: a.status }, js: { out: bo, err: be, rc: b.status } });
  }
}
console.log(`PASS ${pass}/${total}`);
for (const f of fails) {
  console.log('--- COLUMNS=' + JSON.stringify(f.cols), 'ARGS', JSON.stringify(f.argv));
  if (f.py.out !== f.js.out) { console.log('  PY.out', JSON.stringify(f.py.out)); console.log('  JS.out', JSON.stringify(f.js.out)); }
  if (f.py.err !== f.js.err) { console.log('  PY.err', JSON.stringify(f.py.err)); console.log('  JS.err', JSON.stringify(f.js.err)); }
  if (f.py.rc !== f.js.rc) console.log('  RC', f.py.rc, 'vs', f.js.rc);
}
